import { z } from 'zod';
import { FireflyClient, fireflyImages } from '../lib/firefly';
import { spec } from '../spec';

export let generateImage = SlateTool.create(spec, {
  name: 'Generate Image',
  key: 'generate_image',
  description: `Generate images from text prompts using Adobe Firefly AI. Supports customizing image dimensions, content class, style presets, and number of variations. Returns generated image URLs. This is a synchronous API — results are returned directly in the response.`,
  constraints: [
    'Requires enterprise plan with Firefly API access.',
    'Content must comply with Adobe Firefly usage policies.'
  ]
})
  .input(
    z.object({
      prompt: z.string().describe('Text description of the image to generate'),
      negativePrompt: z
        .string()
        .optional()
        .describe('Text describing what to exclude from the generated image'),
      numVariations: z
        .number()
        .optional()
        .describe('Number of image variations to generate (default: 1, max: 4)'),
      width: z.number().optional().describe('Width of generated image in pixels'),
      height: z.number().optional().describe('Height of generated image in pixels'),
      contentClass: z.enum(['photo', 'art']).optional().describe('Content style class'),
      stylePresets: z
        .array(z.string())
        .optional()
        .describe('Style preset identifiers to apply'),
      seeds: z.array(z.number()).optional().describe('Seed values for reproducible results'),
      visualIntensity: z.number().optional().describe('Visual intensity of the style (1-100)'),
      locale: z.string().optional().describe('Locale for prompt interpretation (e.g. en-US)')
    })
  )
  .output(
    z.object({
      images: z.array(
        z.object({
          imageUrl: z.string().describe('URL of the generated image'),
          seed: z.number().optional().describe('Seed value used for this image')
        })
      ),
      contentClass: z.string().optional().describe('Content class applied')
    })
  )
  .handleInvocation(async ctx => {
    let client = new FireflyClient({
      token: [REDACTED],
      clientId: ctx.auth.clientId,
      orgId: ctx.auth.orgId
    });

    let result = await client.generateImages({
      prompt: ctx.input.prompt,
      negativePrompt: ctx.input.negativePrompt,
      numVariations: ctx.input.numVariations,
      size:
        ctx.input.width && ctx.input.height
          ? { width: ctx.input.width, height: ctx.input.height }
          : undefined,
      contentClass: ctx.input.contentClass,
      style: ctx.input.stylePresets
        ? { presets: ctx.input.stylePresets, strength: ctx.input.visualIntensity }
        : undefined,
      seeds: ctx.input.seeds,
      locale: ctx.input.locale
    });

    let images = fireflyImages(result);
    for (let image of images) {
      await ctx.addAttachment({ type: 'url', url: image.imageUrl });
    }

    return {
      output: {
        images,
        contentClass: result.contentClass
      },
      message: `Generated **${images.length}** image(s) from prompt: "${ctx.input.prompt.substring(0, 80)}${ctx.input.prompt.length > 80 ? '...' : ''}"`
    };
  })
  .build();

import { SlateTool } from 'slates';
import { z } from 'zod';
import { Client } from '../lib/client';
import { spec } from '../spec';

export let buyImage = SlateTool.create(spec, {
  name: 'Buy Image',
  key: 'buy_image',
  description: `Purchase a stock image by its ID and receive direct download URLs for preview, full, upscale, and upscale UHD versions. Credits are consumed on first purchase only — subsequent requests for the same image return URLs without additional cost.`,
  constraints: ['Requires sufficient credits in your account.'],
  tags: {
    destructive: false,
    readOnly: false
  }
})
  .input(
    z.object({
      imageId: z.string().describe('ID of the image to purchase')
    })
  )
  .output(
    z.object({
      imageId: z.string().describe('Image ID'),
      previewUrl: z.string().describe('Direct URL to download preview image'),
      fullUrl: z.string().describe('Direct URL to download full image'),
      upscaleUrl: z.string().optional().describe('Direct URL to download upscale image'),
      upscaleUhdUrl: z.string().describe('Direct URL to download upscale UHD image'),
      downloadedAt: z.string().describe('Download timestamp')
    })
  )
  .handleInvocation(async ctx => {
    let client = new Client(ctx.auth.token);

    let image = await client.buyImage(ctx.input.imageId);

    for (let url of new Set([image.fullUrl, image.upscaleUrl, image.upscaleUhdUrl])) {
      if (url) await ctx.addAttachment({ type: 'url', url });
    }

    return {
      output: image,
      message: `Image \`${image.imageId}\` purchased successfully. Full-size and available upscale versions are ready to download.`
    };
  })
  .build();

import { SlateTool } from 'slates';
import { z } from 'zod';
import { Client } from '../lib/client';
import { spec } from '../spec';

export let searchImages = SlateTool.create(spec, {
  name: 'Search Images',
  key: 'search_images',
  description: `Search the All-Images.ai library of AI-generated stock images by keywords. Returns preview and full-size URLs for each matching image. Supports filtering for free-only images and pagination.`,
  tags: {
    readOnly: true
  }
})
  .input(
    z.object({
      search: z.string().optional().describe('Keywords to search for'),
      filterFree: z.boolean().optional().describe('Only return free images'),
      limit: z.number().optional().describe('Number of results per page'),
      offset: z.number().optional().describe('Starting position for pagination'),
      sort: z.string().optional().describe('Provider sort expression')
    })
  )
  .output(
    z.object({
      filteredResults: z.number().optional().describe('Total number of matching images'),
      resultCountMetadata: z
        .unknown()
        .optional()
        .describe('Unmodified provider result count metadata, when provided'),
      images: z
        .array(
          z.object({
            imageId: z.string().describe('Image ID'),
            url: z.string().describe('Preview image URL'),
            urlFull: z.string().describe('Full-size image URL'),
            validated: z
              .boolean()
              .optional()
              .describe('Whether the image was validated by the team'),
            free: z.boolean().optional().describe('Whether the image is free'),
            titles: z
              .record(z.string(), z.string())
              .optional()
              .describe('Image titles by language')
          })
        )
        .describe('Matching images')
    })
  )
  .handleInvocation(async ctx => {
    let client = new Client(ctx.auth.token);

    let result = await client.searchImages({
      search: ctx.input.search,
      filterFree: ctx.input.filterFree,
      limit: ctx.input.limit,
      offset: ctx.input.offset,
      sort: ctx.input.sort
    });

    return {
      output: result,
      message: `${result.filteredResults !== undefined ? `Found **${result.filteredResults}** images. ` : ''}Returned **${result.images.length}** results${ctx.input.search ? ` matching "${ctx.input.search}"` : ''}.`
    };
  })
  .build();

import { SlateTool } from 'slates';
import { z } from 'zod';
import { Client } from '../lib/client';
import { spec } from '../spec';

export let editImage = SlateTool.create(spec, {
  name: 'Edit Image',
  key: 'edit_image',
  description:
    'Edit existing images with a text instruction, such as removing an object, changing a background, or adding a detail. Provide publicly accessible source image URLs as context.',
  instructions: [
    'Describe the change clearly and supply one or more contextImageUrls.',
    'If processing is still pending, call get_job_result with the returned jobId.'
  ],
  tags: { destructive: false, readOnly: false }
})
  .input(
    z.object({
      prompt: z.string().min(1).describe('Text instruction describing the desired edit'),
      contextImageUrls: z
        .array(z.url())
        .min(1)
        .describe('Publicly accessible URLs of the source and reference images'),
      modelType: z
        .enum(['gemini-3-pro-image-preview', 'google-gemini-image-flash', 'qwen'])
        .optional()
        .describe('AI editing model; defaults to gemini-3-pro-image-preview'),
      width: z.number().optional().describe('Target output width in whole pixels'),
      height: z.number().optional().describe('Target output height in whole pixels'),
      outputFormat: z.enum(['jpg', 'png', 'webp']).optional().describe('Output image format')
    })
  )
  .output(
    z.object({
      status: z.string().describe('Processing status'),
      jobId: z.string().describe('Job identifier for tracking'),
      resultUrl: z.string().optional().describe('URL to the edited image when complete')
    })
  )
  .handleInvocation(async ctx => {
    let client = new Client({ token: [REDACTED] });
    let result = await client.processImageSync({
      width: ctx.input.width,
      height: ctx.input.height,
      outputFormat: ctx.input.outputFormat,
      background: {
        generate: {
          description: ctx.input.prompt,
          adapterType: 'img2img',
          modelType: ctx.input.modelType ?? 'gemini-3-pro-image-preview',
          contextImages: ctx.input.contextImageUrls
        }
      }
    });

    if (result.status === 'complete' && result.resultUrl) {
      await ctx.addAttachment({ type: 'url', url: result.resultUrl });
    }

    return {
      output: result,
      message:
        result.status === 'complete'
          ? `Image edited successfully. Result: ${result.resultUrl}`
          : `Image editing started (status: **${result.status}**). Job ID: \`${result.jobId}\`.`
    };
  })
  .build();

